require_once dirname(__DIR__,2).'/app/bootstrap.php';require_owner();$id=(int)($_GET['id']??$_POST['id']??0);$s=db()->prepare('SELECT * FROM listings WHERE id=:id AND owner_user_id=:u');$s->execute([':id'=>$id,':u'=>current_user_id()]);$l=$s->fetch();if(!$l){http_response_code(404);exit('This listing is not assigned to your account.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['phone','email','website','address','location','city','whatsapp','price_range','opening_hours','description','tags'] as $k)$l[$k]=trim((string)($_POST[$k]??''));$lat=trim((string)($_POST['latitude']??''));$lng=trim((string)($_POST['longitude']??''));if($l['email']!==''&&!filter_var($l['email'],FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';$web=valid_http_url($l['website']);if($l['website']!==''&&!$web)$errors[]='Enter a valid website URL.';if(text_len($l['description'])<30)$errors[]='Description must contain at least 30 characters.';$latitude=$lat===''?null:filter_var($lat,FILTER_VALIDATE_FLOAT);$longitude=$lng===''?null:filter_var($lng,FILTER_VALIDATE_FLOAT);if($lat!==''&&($latitude===false||$latitude < -90||$latitude>90))$errors[]='Latitude must be between -90 and 90.';if($lng!==''&&($longitude===false||$longitude < -180||$longitude>180))$errors[]='Longitude must be between -180 and 180.';try{$upload=upload_listing_image($_FILES['image']??['error'=>UPLOAD_ERR_NO_FILE]);if($upload){delete_uploaded_image($l['image_path']);$l['image_path']=$upload;}}catch(Throwable $e){$errors[]=$e->getMessage();}if(!$errors){db()->prepare('UPDATE listings SET phone=:p,email=:e,website=:w,address=:a,location=:loc,city=:city,whatsapp=:wa,price_range=:pr,opening_hours=:oh,description=:d,tags=:t,latitude=:lat,longitude=:lng,image_path=:ip,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND owner_user_id=:u')->execute([':p'=>$l['phone'],':e'=>$l['email'],':w'=>$web,':a'=>$l['address'],':loc'=>$l['location'],':city'=>$l['city'],':wa'=>$l['whatsapp'],':pr'=>$l['price_range'],':oh'=>$l['opening_hours'],':d'=>$l['description'],':t'=>$l['tags'],':lat'=>$latitude,':lng'=>$longitude,':ip'=>$l['image_path'],':id'=>$id,':u'=>current_user_id()]);flash('success','Business profile updated.');redirect(app_path('owner/index.php'));}}
$ownerTitle='Edit business profile';include __DIR__.'/_header.php';?><?php if($errors): ?><div class="alert alert-error"><ul><?php foreach($errors as $e): ?><li><?= h($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form class="admin-panel editor-form" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="panel-subhead"><h2><?= h($l['name']) ?></h2><span>Listing changes are saved immediately.</span></div><div class="form-grid"><label>Neighbourhood<input name="location" required value="<?= h($l['location']) ?>"></label><label>City / district<input name="city" value="<?= h($l['city']) ?>"></label><label>Street address<input name="address" value="<?= h($l['address']) ?>"></label><label>Business phone<input name="phone" value="<?= h($l['phone']) ?>"></label><label>Business email<input type="email" name="email" value="<?= h($l['email']) ?>"></label><label>Website<input name="website" value="<?= h($l['website']) ?>"></label><label>WhatsApp number<input name="whatsapp" value="<?= h($l['whatsapp']) ?>"></label><label>Price range<input name="price_range" value="<?= h($l['price_range']) ?>" placeholder="e.g. ₹₹ or ₹200–₹500"></label><label>Latitude<input name="latitude" value="<?= h((string)$l['latitude']) ?>" placeholder="22.5726"></label><label>Longitude<input name="longitude" value="<?= h((string)$l['longitude']) ?>" placeholder="88.3639"></label></div><label>Opening hours<textarea name="opening_hours" rows="3" placeholder="Mon–Sat: 10:00 AM–8:00 PM"><?= h($l['opening_hours']) ?></textarea></label><label>Highlights / tags<input name="tags" value="<?= h($l['tags']) ?>"></label><label>Business description<textarea name="description" minlength="30" rows="5" required><?= h($l['description']) ?></textarea></label><label>Update main photo<input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"><small>JPG, PNG, WEBP or GIF up to 3 MB.</small></label><div class="editor-actions"><a class="button button-outline" href="<?= app_path('owner/index.php') ?>">Cancel</a><button class="button button-primary">Save business details</button></div></form><?php include __DIR__.'/_footer.php';?>
